import 'dart:convert';

import 'package:api_client/api_client.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// {@template scryfall_bulk_client}
/// Client for searching the bundled commander index asset.
///
/// The asset is a compact projection of Scryfall's unique-artwork bulk data
/// containing only commander-eligible cards (type line with "Legendary" or
/// "Background") and only the fields the app reads. It is generated by
/// `tool/generate_commander_index.dart` — see the package README.
///
/// The index is parsed on a background isolate on first use and cached,
/// then provides fast in-memory card name search and oracle ID lookup that
/// both work offline.
/// {@endtemplate}
class ScryfallBulkClient {
  /// {@macro scryfall_bulk_client}
  ScryfallBulkClient({AssetBundle? assetBundle})
    : _assetBundle = assetBundle ?? rootBundle;

  final AssetBundle _assetBundle;

  static const _assetPath =
      'packages/scryfall_bulk_client/assets/cards/commander_index.json';

  /// Cached as futures so concurrent first calls share a single load.
  Future<List<MagicCard>>? _cardsFuture;
  Future<Map<String, String>>? _oracleIdsFuture;

  /// Loads and caches the commander index asset on first call.
  Future<List<MagicCard>> _loadCards() => _cardsFuture ??= _assetBundle
      .loadString(_assetPath)
      .then((jsonString) => compute(_parseCommanderIndex, jsonString));

  Future<Map<String, String>> _loadOracleIds() =>
      _oracleIdsFuture ??= _loadCards().then(
        (cards) => {
          for (final card in cards)
            if (card.oracleId != null) card.name.toLowerCase(): card.oracleId!,
        },
      );

  /// Finds a card by exact name (case-insensitive) and returns its oracle ID.
  ///
  /// Only commander-eligible cards are indexed. Returns `null` if no card
  /// matches the exact name.
  Future<String?> getOracleIdByName(String cardName) async {
    final oracleIds = await _loadOracleIds();
    return oracleIds[cardName.toLowerCase()];
  }

  /// Searches the local commander index for cards whose name contains
  /// [query] (case-insensitive).
  ///
  /// Returns a [SearchCards] object compatible with the rest of the data
  /// layer. Returns an empty result set if no cards match.
  Future<SearchCards> searchCards(String query) async {
    final cards = await _loadCards();
    final lowerQuery = query.toLowerCase();
    final matches = cards
        .where((card) => card.name.toLowerCase().contains(lowerQuery))
        .toList();
    return SearchCards(
      object: 'list',
      totalCards: matches.length,
      hasMore: false,
      nextPage: null,
      data: matches,
    );
  }
}

List<MagicCard> _parseCommanderIndex(String jsonString) {
  final jsonList = jsonDecode(jsonString) as List<dynamic>;
  return jsonList
      .map((e) => _cardFromIndexEntry(e as Map<String, dynamic>))
      .toList();
}

/// Builds a [MagicCard] from a compact index entry.
///
/// The index only stores the fields the app reads (see
/// `tool/generate_commander_index.dart`); everything else is filled with
/// neutral defaults. The single stored `art_crop` URL backs every
/// [ImageURIs] variant since the app only ever renders art crops.
MagicCard _cardFromIndexEntry(Map<String, dynamic> entry) {
  final artCrop = entry['art_crop'] as String?;
  return MagicCard(
    object: 'card',
    id: '',
    oracleId: entry['oracle_id'] as String?,
    mtgoId: null,
    arenaId: null,
    multiverseIds: null,
    tcgplayerId: null,
    tcgplayerEtchedId: null,
    mtgoFoilId: null,
    cardmarketId: null,
    name: entry['name'] as String,
    lang: 'en',
    releasedAt: '',
    uri: '',
    scryfallUri: (entry['scryfall_uri'] as String?) ?? '',
    layout: 'normal',
    highresImage: true,
    imageStatus: artCrop != null ? 'highres_scan' : 'missing',
    imageUris: artCrop == null
        ? null
        : ImageURIs(
            small: artCrop,
            normal: artCrop,
            large: artCrop,
            png: artCrop,
            artCrop: artCrop,
            borderCrop: artCrop,
          ),
    manaCost: entry['mana_cost'] as String?,
    allParts: null,
    cardFaces: null,
    cmc: null,
    lifeModifier: null,
    loyalty: null,
    power: entry['power'] as String?,
    producedMana: null,
    toughness: entry['toughness'] as String?,
    typeLine: entry['type_line'] as String?,
    oracleText: entry['oracle_text'] as String?,
    colors: (entry['colors'] as List<dynamic>?)?.cast<String>(),
    colorIndicator: null,
    colorIdentity:
        (entry['color_identity'] as List<dynamic>?)?.cast<String>() ?? [],
    keywords: (entry['keywords'] as List<dynamic>?)?.cast<String>() ?? [],
    legalities: _indexLegalities,
    games: const [],
    reserved: false,
    foil: false,
    nonfoil: true,
    finishes: const [],
    oversized: false,
    promo: false,
    reprint: false,
    variation: false,
    setId: '',
    set: '',
    setName: '',
    setType: '',
    setUri: '',
    setSearchUri: '',
    scryfallSetUri: '',
    rulingsUri: '',
    printsSearchUri: '',
    collectorNumber: '',
    digital: false,
    rarity: '',
    cardBackId: null,
    artist: entry['artist'] as String?,
    contentWarning: null,
    flavorName: null,
    flavorText: null,
    artistIds: null,
    illustrationId: null,
    borderColor: '',
    frame: '',
    securityStamp: null,
    fullArt: false,
    textless: false,
    booster: false,
    storySpotlight: false,
    edhrecRank: entry['edhrec_rank'] as int?,
    pennyRank: null,
    handModifier: null,
    prices: _emptyPrices,
    relatedUris: _emptyRelatedUris,
    purchaseUris: null,
  );
}

const _emptyPrices = Prices(
  usd: null,
  usdFoil: null,
  usdEtched: null,
  eur: null,
  eurFoil: null,
  tix: null,
);

const _emptyRelatedUris = RelatedURIs(
  gatherer: null,
  tcgplayerInfiniteArticles: null,
  tcgplayerInfiniteDecks: null,
  edhrec: null,
);

const _indexLegalities = Legalities(
  standard: '',
  future: '',
  historic: '',
  gladiator: '',
  pioneer: '',
  timeless: '',
  modern: '',
  legacy: '',
  pauper: '',
  vintage: '',
  penny: '',
  commander: 'legal',
  oathbreaker: '',
  brawl: '',
  historicbrawl: null,
  alchemy: '',
  paupercommander: '',
  duel: '',
  oldschool: '',
  premodern: '',
  predh: '',
);
